// === NAME - DESCRIPTION:  ===
// === SET QUESTION TYPE TO: choices ===

// === COMMON CONTROL ===
// randfrom expects an array as its only argument
$type = randfrom(array(0, 1, 2));

if ($type == 0) {
    // Ordered Pairs: Function
    $x_vals = diffrands(0, 10, 4);
    $y_vals = array();
    for ($i = 0; $i < 4; $i++) {
        $y_vals[] = rand(0, 10);
    }
    $pairs = "";
    for ($i = 0; $i < 4; $i++) {
        $pairs .= "(" . $x_vals[$i] . ", " . $y_vals[$i] . ")";
        if ($i < 3) $pairs .= ", ";
    }
    $prompt = "the set of ordered pairs " . $pairs;
    $is_func = 0; // Index 0 for "Yes"
} elseif ($type == 1) {
    // Ordered Pairs: Not a Function (one x maps to two y)
    $x_vals = diffrands(0, 10, 3);
    $y_vals = array();
    for ($i = 0; $i < 4; $i++) {
        $y_vals[] = rand(0, 10);
    }
    while ($y_vals[0] == $y_vals[1]) {
        $y_vals[1] = rand(0, 10);
    }
    $pairs = "(" . $x_vals[0] . ", " . $y_vals[0] . "), (" . $x_vals[0] . ", " . $y_vals[1] . ")";
    for ($i = 1; $i < 3; $i++) {
        $pairs .= ", (" . $x_vals[$i] . ", " . $y_vals[$i+1] . ")";
    }
    $prompt = "the set of ordered pairs " . $pairs;
    $is_func = 1; // Index 1 for "No"
} else {
    // Mapping Diagram: Scenario based
    $scenarios = array(
        array("A mapping diagram where the input 2 maps to 5, and the input 2 also maps to 8", 1),
        array("A mapping diagram where the input 1 maps to 4, the input 2 maps to 4, and the input 3 maps to 4", 0),
        array("A mapping diagram where the input 5 maps to 10, the input 6 maps to 11, and the input 7 maps to 12", 0),
        array("A mapping diagram where the input 0 maps to 1, and the input 0 also maps to 2", 1)
    );
    $pick = randfrom($scenarios);
    $prompt = $pick[0];
    $is_func = $pick[1];
}

$questions = array("Yes, it is a function", "No, it is not a function");
$answer = $is_func;

// === QUESTION TEXT ===
Determine if the following relationship is a function:

<p>$prompt</p>

$answerbox

// === ANSWER ===
if ($answer == 0) {
    $solutionguide = 'A relationship is a function if every input (x-value) is associated with exactly one output (y-value). In this case, no input is repeated with a different output, so it is a function.';
} else {
    $solutionguide = 'A relationship is not a function if at least one input (x-value) is associated with more than one output (y-value). In this case, an input is repeated with different outputs, so it is not a function.';
}

// === NAME - DESCRIPTION: Bar Graph of Counts Versus Percentages - Recover group size and compare shapes ===
// === SET QUESTION TYPE TO: multipart ===

// === COMMON CONTROL ===
$categories = array("Red", "Blue", "Green", "Yellow");
$cat_count = count($categories);

// Generate counts that sum to a nice number for percentages
$total_n = randfrom(array(40, 50, 60, 80, 100));

// Distribute total_n across categories
$counts = array();
$remaining = $total_n;
for ($i = 0; $i < $cat_count - 1; $i++) {
    $val = rand(2, floor($remaining / 2));
    $counts[] = $val;
    $remaining -= $val;
}
$counts[] = $remaining;

// Shuffle categories and counts together
jointshuffle($categories, $counts);

$disp_cats = $categories;
$disp_counts = $counts;

// Pick one category for the percentage calculation part
$target_idx = rand(0, $cat_count - 1);
$target_cat = $disp_cats[$target_idx];
$target_val = $disp_counts[$target_idx];
$target_pct = ($target_val / $total_n) * 100;

// Part (a): Total group size
$answer[0] = $total_n;

// Part (b): Percentage for the target category
$answer[1] = $target_pct;

// Part (c): Why the shape is the same
$questions[2] = array(
    "The percentages are calculated by dividing each count by the same total, so the relative heights remain the same.",
    "The percentages are calculated by adding the total to each count, so the relative heights remain the same.",
    "The percentages are calculated by multiplying each count by the total, so the relative heights remain the same.",
    "The shape changes slightly, but it is too small to see on a bar graph."
);
$answer[2] = 0;

$anstypes = "number,number,choices";

// Build the tables for display
$table_counts = "<table border='1' style='border-collapse: collapse; text-align: center;'><tr><th>Category</th><th>Count</th></tr>";
for ($i = 0; $i < $cat_count; $i++) {
    $table_counts .= "<tr><td>{$disp_cats[$i]}</td><td>{$disp_counts[$i]}</td></tr>";
}
$table_counts .= "</table>";

$table_pcts = "<table border='1' style='border-collapse: collapse; text-align: center;'><tr><th>Category</th><th>Percentage</th></tr>";
for ($i = 0; $i < $cat_count; $i++) {
    if ($i == $target_idx) {
        $val_str = "???";
    } else {
        $p = ($disp_counts[$i] / $total_n) * 100;
        $val_str = round($p, 1) . "%";
    }
    $table_pcts .= "<tr><td>{$disp_cats[$i]}</td><td>{$val_str}</td></tr>";
}
$table_pcts .= "</table>";

$solutionguide = "Part (a): The total group size is the sum of all counts: " . arraytolist($disp_counts, " + ") . " = $total_n. Part (b): The percentage for $target_cat is (" . $target_val . " / " . $total_n . ") * 100 = " . round($target_pct, 2) . "%. Part (c): Since every bar is scaled by the same constant (1/N), the relative proportions of the bars do not change, leaving the shape of the graph identical.";

// === QUESTION TEXT ===
<p>A researcher collected data on the favorite colors of a group of participants. The data is summarized in the two tables below.</p>

<p><strong>Table 1: Counts</strong><br/>
$table_counts</p>

<p><strong>Table 2: Percentages</strong><br/>
$table_pcts</p>

<p>(a) What was the total number of participants in the group? <br/>
Answer: $answerbox[0]</p>

<p>(b) Based on the counts, what percentage of the group chose $target_cat? <br/>
(Round your answer to two decimal places) <br/>
Answer: $answerbox[1]%</p>

<p>(c) If you were to create a bar graph for the counts and a bar graph for the percentages, you would notice that the overall shape of the two graphs is identical. Why is this the case? <br/>
$answerbox[2]</p>

// === NAME - DESCRIPTION:  ===
// === SET QUESTION TYPE TO: multipart ===

// === COMMON CONTROL ===
// Generate probabilities as whole number percentages first to ensure clean decimals
$pA_pct = rand(20, 50);
$pA = $pA_pct / 100;

$pB_pct = rand(20, 50);
$pB = $pB_pct / 100;

// Ensure P(A and B) is possible: must be <= min(pA, pB)
$maxOverlap_pct = min($pA_pct, $pB_pct);
// Ensure overlap is at least 5% and at most the smaller of the two
$pAandB_pct = rand(5, $maxOverlap_pct);
$pAandB = $pAandB_pct / 100;

// Calculate P(A or B) = P(A) + P(B) - P(A and B)
$pAorB = $pA + $pB - $pAandB;

// For the choices part
$wrongSum = $pA + $pB;

$answer[0] = $pAorB;
$answer[1] = 0; // Index of the correct explanation

$questions[1][0] = "Adding `P(A)` and `P(B)` together counts the outcomes in both sets twice.";
$questions[1][1] = "Adding `P(A)` and `P(B)` together ignores the outcomes that are in both sets.";
$questions[1][2] = "The Addition Rule only applies if the events are mutually exclusive.";
$questions[1][3] = "The probability of a union is always the product of the individual probabilities.";

$anstypes = "number,choices";

// === QUESTION TEXT ===
In a probability experiment, two events `A` and `B` have the following probabilities:
<p>`P(A) = $pA`</p>
<p>`P(B) = $pB`</p>
<p>`P(A \text{ and } B) = $pAandB`</p>

<p>(a) Find the probability that event `A` or event `B` occurs. 
Enter your answer as a decimal (e.g., 0.45).<br>
`P(A \text{ or } B) =` $answerbox[0]</p>

<p>(b) If you simply added `P(A) + P(B)`, your result would be `$wrongSum`, which is different from the correct answer. Why is this simple sum incorrect?</p>
$answerbox[1]

// === ANSWER ===
$solutionguide = "To find the probability of the union of two events, we use the Addition Rule: 
`P(A \text{ or } B) = P(A) + P(B) - P(A \text{ and } B)`.
Substituting the given values:
`P(A \text{ or } B) = $pA + $pB - $pAandB = $pAorB`.
We subtract the overlap `P(A \text{ and } B)` because those outcomes are included in both `P(A)` and `P(B)`. Adding the two probabilities without subtracting the overlap counts those shared outcomes twice.";

// === NAME - DESCRIPTION:  ===
// === SET QUESTION TYPE TO: multipart ===

// === COMMON CONTROL ===
// We need a 2x2 table. To ensure expected counts are reasonable, we pick a total N and distribute it.
$nTotal = rand(100, 300);

// Row 1 total (e.g., "Group A")
$row1Total = rand(40, $nTotal - 40);
$row2Total = $nTotal - $row1Total;

// Col 1 total (e.g., "Success")
$col1Total = rand(40, $nTotal - 40);
$col2Total = $nTotal - $col1Total;

// Expected = (Row Total * Col Total) / Grand Total
$exp11 = ($row1Total * $col1Total) / $nTotal;
$exp12 = ($row1Total * $col2Total) / $nTotal;
$exp21 = ($row2Total * $col1Total) / $nTotal;
$exp22 = ($row2Total * $col2Total) / $nTotal;

$answer[0] = round($exp11, 2);
$answer[1] = round($exp12, 2);
$answer[2] = round($exp21, 2);

$anstypes = "number,number,number";

// Context randomization
$contexts = array(
    array("Treatment", "Control", "Improved", "No Improvement"),
    array("Men", "Women", "Pass", "Fail"),
    array("City Residents", "Rural Residents", "Support Policy", "Oppose Policy"),
    array("New Method", "Old Method", "Correct", "Incorrect")
);
$ctx = randfrom($contexts);
$rowLabel1 = $ctx[0];
$rowLabel2 = $ctx[1];
$colLabel1 = $ctx[2];
$colLabel2 = $ctx[3];

// To ensure all observed counts are non-negative:
// obs11 must be <= row1Total and <= col1Total
// obs21 = col1Total - obs11 >= 0  => obs11 <= col1Total
// obs12 = row1Total - obs11 >= 0  => obs11 <= row1Total
// obs22 = row2Total - obs21 = row2Total - (col1Total - obs11) >= 0
// obs11 >= col1Total - row2Total = col1Total - (nTotal - row1Total) = col1Total + row1Total - nTotal
$minObs11 = max(0, $row1Total + $col1Total - $nTotal);
$maxObs11 = min($row1Total, $col1Total);
$obs11 = rand($minObs11, $maxObs11);

$obs12 = $row1Total - $obs11;
$obs21 = $col1Total - $obs11;
$obs22 = $row2Total - $obs21;

$solutionguide = 'The expected count for a cell in a contingency table is calculated using the formula: 
Expected Count = (Row Total * Column Total) / Grand Total

For the first cell (' . $rowLabel1 . ' and ' . $colLabel1 . '): 
Expected = (' . $row1Total . ' * ' . $col1Total . ') / ' . $nTotal . ' = ' . round($exp11, 4) . '

For the second cell (' . $rowLabel1 . ' and ' . $colLabel2 . '): 
Expected = (' . $row1Total . ' * ' . $col2Total . ') / ' . $nTotal . ' = ' . round($exp12, 4) . '

For the third cell (' . $rowLabel2 . ' and ' . $colLabel1 . '): 
Expected = (' . $row2Total . ' * ' . $col1Total . ') / ' . $nTotal . ' = ' . round($exp21, 4) . '

Round your answers to two decimal places.';

