// === NAME - DESCRIPTION: Normal Distribution - Critical Z and Area Selection ===
// === SET QUESTION TYPE TO: multipart ===

// === COMMON CONTROL ===
loadlibrary("stats");

// Generate a right-tail area and round it immediately to 3 decimals to ensure 
// the student's calculation matches the key exactly.
$rightArea = round(1 / (rand(10, 20) + 0.5), 3); 
$leftArea = 1 - $rightArea;
$zRight = invnormalcdf($leftArea, 0, 1);

// Middle percentage
$midPct = randfrom([0.90, 0.95, 0.98, 0.99]);
$tailArea = (1 - $midPct) / 2;
$zMid = invnormalcdf(1 - $tailArea, 0, 1);

$anstypes = "choices,number,number";

// Part 1 Choices: Use the rounded $rightArea so the options match the prompt.
$questions[0] = array(
  "$rightArea", 
  "1 - $rightArea", 
  "0.5 - $rightArea", 
  "1 - 2 * $rightArea"
);
$answer[0] = 1; // Index of "1 - $rightArea"

// Part 2 Answer: Computed from the rounded area.
$answer[1] = round($zRight, 3);

// Part 3 Answer
$answer[2] = round($zMid, 3);

$midPctDisp = $midPct * 100;

// Solution Guide
$solutionguide = "Part (a): The invNorm function always calculates the area to the left of a z-score. To find the z-score that leaves an area of $rightArea in the right tail, we must provide the area to the left, which is 1 - $rightArea = " . round($leftArea, 3) . ".
Part (b): Using invNorm(" . round($leftArea, 3) . ", 0, 1), we find z = " . round($zRight, 3) . ".
Part (c): For the middle $midPctDisp%, the remaining area is " . round(1 - $midPct, 3) . ". This is split equally between two tails, so each tail has an area of " . round($tailArea, 4) . ". The positive critical value is found using invNorm(" . round(1 - $tailArea, 4) . ", 0, 1), which gives z = " . round($zMid, 3) . ".";

// === QUESTION TEXT ===
<p>Consider the standard normal distribution (mean = 0, standard deviation = 1).</p>

<p>(a) You want to find the critical value `z` such that the area in the <b>right tail</b> is `$rightArea`. Since the `invNorm` function calculates the area to the <b>left</b> of a value, which area should you enter into the function to find this `z`?</p>
$answerbox[0]

<p>(b) Using the area identified in part (a), find the critical value `z`. Round your answer to three decimal places.</p>
`z =` $answerbox[1]

<p>(c) Find the positive critical value `z` that bounds the middle `$midPctDisp`% of the standard normal curve. Round your answer to three decimal places.</p>
`z =` $answerbox[2]

// === NAME - DESCRIPTION: Reading a Study - Classify study type, identify bias/confounding, and determine justified conclusions ===
// === SET QUESTION TYPE TO: multipart ===

// === COMMON CONTROL ===
$scenarios = [
  [
    "text" => "A researcher wants to study the effect of a new vitamin supplement on memory. She recruits 100 volunteers and asks them to take the supplement every morning for six months. At the end of the period, she gives them a memory test and finds that those who took the supplement scored higher than the average score of a similar group of people who did not take the supplement.",
    "type" => "observational",
    "bias" => "self-selection bias",
    "confounding" => "health consciousness",
    "justified" => "there is an association between taking the supplement and higher memory scores",
    "not_justified" => "the supplement caused the increase in memory scores"
  ],
  [
    "text" => "A nutritionist wants to see if eating blueberries improves focus. He randomly assigns 50 students to eat a bowl of blueberries every morning and 50 students to eat a bowl of sliced apples every morning. After one month, he measures their focus levels using a standardized test.",
    "type" => "experimental",
    "bias" => "placebo effect",
    "confounding" => "daily sleep patterns",
    "justified" => "eating blueberries causes an improvement in focus compared to eating apples",
    "not_justified" => "blueberries are the only way to improve focus"
  ],
  [
    "text" => "A public health official wants to know if living near a park reduces stress. She surveys 200 residents of a city, recording whether they live within a mile of a park and their reported stress levels on a scale of 1 to 10.",
    "type" => "observational",
    "bias" => "sampling bias",
    "confounding" => "income level",
    "justified" => "there is an association between living near a park and lower stress levels",
    "not_justified" => "living near a park causes a reduction in stress"
  ]
];

$sIdx = rand(0, 2);
$scenario = $scenarios[$sIdx];
$scenarioText = $scenario['text'];
$scenarioType = $scenario['type'];
$scenarioBias = $scenario['bias'];
$scenarioConfound = $scenario['confounding'];
$scenarioJust = $scenario['justified'];
$scenarioNotJust = $scenario['not_justified'];

$anstypes = "choices,essay,essay";

$questions[0] = [
  "Is this study observational or experimental?",
  "Observational",
  "Experimental"
];
$answer[0] = ($scenarioType == "observational") ? 0 : 1;

// For essay parts, we provide a model answer for the teacher/student.
$answer[1] = $scenarioBias . " or " . $scenarioConfound;
$answer[2] = "Justified: " . $scenarioJust . "; Not Justified: " . $scenarioNotJust;

$strflags[0] = "ignore_case,trim_whitespace";
$strflags[1] = "ignore_case,trim_whitespace";
$strflags[2] = "ignore_case,trim_whitespace";

$reason = ($scenarioType == "experimental") ? "the researcher used random assignment to impose a treatment." : "the researcher did not use random assignment to impose a treatment.";
$solutionguide = "Step 1: The study is " . $scenarioType . " because " . $reason . " Step 2: A plausible source of bias or confounding is " . $scenarioBias . " or " . $scenarioConfound . ". Step 3: A justified conclusion is that " . $scenarioJust . ". A conclusion that is NOT justified is that " . $scenarioNotJust . ".";

// === QUESTION TEXT ===
<p>Consider the following study:</p>
<blockquote style="font-style: italic;">$scenarioText</blockquote>

<p><b>(a)</b> Is this study observational or experimental? <br>
$answerbox[0]</p>

<p><b>(b)</b> Name a plausible source of bias or a confounding variable that could affect the results of this study: <br>
$answerbox[1]</p>

<p><b>(c)</b> State one conclusion that is justified by the results of this study, and one conclusion that is NOT justified: <br>
$answerbox[2]</p>

// === ANSWER ===
$solutionguide = $solutionguide;

// === NAME - DESCRIPTION:  ===
// === SET QUESTION TYPE TO: number ===

// === COMMON CONTROL ===
$bases = [2, 3, 4];
$base = randfrom($bases);

// Generate a result that is a positive integer
// We keep the result small enough that the argument doesn't become astronomically large
$result = rand(2, 6);

// Calculate the argument: base^result
$argument = $base ** $result;

// The answer is the exponent
$answer = $result;

// Solution guide construction
$solutionguide = "To evaluate `log_{$base}($argument)`, we look for the exponent that the base `$base` must be raised to in order to get `$argument`. Since `$base^{$result} = $argument`, the value of the logarithm is $result.";

// === QUESTION TEXT ===
Evaluate the following logarithm:

`log_{$base}($argument) =` $answerbox

// === ANSWER ===
$solutionguide = $solutionguide;

// === NAME - DESCRIPTION:  ===
// === SET QUESTION TYPE TO: choices ===

// === COMMON CONTROL ===
// 0 = Linear, 1 = Quadratic/Curved.
$type = rand(0, 1);

// Generate 10 points
$x_vals = array();
$y_vals = array();
for ($i = 0; $i < 10; $i++) {
    $x = $i + 1;
    $x_vals[] = $x;
    if ($type == 0) {
        // Linear: y = 2x + 5 + noise
        $noise = rand(-3, 3);
        $y = 2 * $x + 5 + $noise;
    } else {
        // Non-linear: y = x^2 + noise
        $noise = rand(-2, 2);
        $y = $x * $x + $noise;
    }
    $y_vals[] = $y;
}

// Calculate a simple linear fit (Least Squares) for the line to be drawn
$sumX = 0; $sumY = 0; $sumXY = 0; $sumX2 = 0;
$n = count($x_vals);
for ($i = 0; $i < $n; $i++) {
    $sumX += $x_vals[$i];
    $sumY += $y_vals[$i];
    $sumXY += $x_vals[$i] * $y_vals[$i];
    $sumX2 += $x_vals[$i] * $x_vals[$i];
}
$slope = ($n * $sumXY - $sumX * $sumY) / ($n * $sumX2 - $sumX * $sumX);
$intercept = ($sumY - $slope * $sumX) / $n;

// Determine the correct answer based on the type
if ($type == 0) {
    $answer = 0; // "Yes"
} else {
    $answer = 1; // "No"
}

$questions[0] = "Yes, the data points scatter around a roughly linear trend.";
$questions[1] = "No, the data points do not follow a roughly linear trend.";

// Create the SVG scatterplot
$width = 450;
$height = 350;
$padding = 50;
$plot_w = $width - 2 * $padding;
$plot_h = $height - 2 * $padding;

// Scale factors
$min_x = 0; $max_x = 11;
$min_y = min($y_vals) - 2; $max_y = max($y_vals) + 2;

$scale_x = $plot_w / ($max_x - $min_x);
$scale_y = $plot_h / ($max_y - $min_y);

$points_svg = "";
foreach ($x_vals as $idx => $vx) {
    $vy = $y_vals[$idx];
    $cx = $padding + ($vx - $min_x) * $scale_x;
    $cy = $height - $padding - ($vy - $min_y) * $scale_y;
    $points_svg .= "<circle cx='$cx' cy='$cy' r='4' fill='blue' />";
}

// Clip the line to the visible plot area to prevent clipping labels
// We find where the line intersects the plot boundaries
$lx1 = $min_x;
$ly1 = $slope * $lx1 + $intercept;
$lx2 = $max_x;
$ly2 = $slope * $lx2 + $intercept;

// Clamp y values to the plot range to keep the line inside the axes
if ($ly1 < $min_y) {
    $ly1 = $min_y;
    $lx1 = ($ly1 - $intercept) / $slope;
} elseif ($ly1 > $max_y) {
    $ly1 = $max_y;
    $lx1 = ($ly1 - $intercept) / $slope;
}

if ($ly2 < $min_y) {
    $ly2 = $min_y;
    $lx2 = ($ly2 - $intercept) / $slope;
} elseif ($ly2 > $max_y) {
    $ly2 = $max_y;
    $lx2 = ($ly2 - $intercept) / $slope;
}

// Final clamp for x to ensure it doesn't bleed outside padding
$lx1 = max($min_x, min($max_x, $lx1));
$lx2 = max($min_x, min($max_x, $lx2));

$line_x1 = $padding + ($lx1 - $min_x) * $scale_x;
$line_y1 = $height - $padding - ($ly1 - $min_y) * $scale_y;
$line_x2 = $padding + ($lx2 - $min_x) * $scale_x;
$line_y2 = $height - $padding - ($ly2 - $min_y) * $scale_y;

$line_svg = "<line x1='$line_x1' y1='$line_y1' x2='$line_x2' y2='$line_y2' stroke='red' stroke-width='2' />";

// Draw axes
$axes = "<line x1='$padding' y1='".($height - $padding)."' x2='".($width - $padding)."' y2='".($height - $padding)."' stroke='black' stroke-width='2' />"; // X
$axes .= "<line x1='$padding' y1='$padding' x2='$padding' y2='".($height - $padding)."' stroke='black' stroke-width='2' />"; // Y

// Add tick labels
$ticks_svg = "";
