// We need a 3x3 matrix A that is invertible.
$det = 0;
while ($det == 0) {
  $a11 = rand(-5, 5); $a12 = rand(-5, 5); $a13 = rand(-5, 5);
  $a21 = rand(-5, 5); $a22 = rand(-5, 5); $a23 = rand(-5, 5);
  $a31 = rand(-5, 5); $a32 = rand(-5, 5); $a33 = rand(-5, 5);

  // Determinant of 3x3
  $det = $a11*($a22*$a33 - $a23*$a32) - $a12*($a21*$a33 - $a23*$a31) + $a13*($a21*$a32 - $a22*$a31);
}

// Calculate Adjugate matrix for A^-1 = (1/det) * adj(A)
$c11 = ($a22*$a33 - $a23*$a32);
$c12 = -($a21*$a33 - $a23*$a31);
$c13 = ($a21*$a32 - $a22*$a31);
$c21 = -($a12*$a33 - $a13*$a32);
$c22 = ($a11*$a33 - $a13*$a31);
$c23 = -($a11*$a32 - $a12*$a31);
$c31 = ($a12*$a23 - $a13*$a22);
$c32 = -($a11*$a23 - $a13*$a21);
$c33 = ($a11*$a22 - $a12*$a21);

$inv11 = $c11 / $det; $inv12 = $c12 / $det; $inv13 = $c13 / $det;
$inv21 = $c21 / $det; $inv22 = $c22 / $det; $inv23 = $c23 / $det;
$inv31 = $c31 / $det; $inv32 = $c32 / $det; $inv33 = $c33 / $det;

// For 'matrix' answer type, the answer must be a flat array of arrays.
$answer[0] = array(
  array($inv11, $inv12, $inv13),
  array($inv21, $inv22, $inv23),
  array($inv31, $inv32, $inv33)
);

// Generate B such that X = A^-1 * B results in integers for X
$x1 = rand(-5, 5);
$x2 = rand(-5, 5);
$x3 = rand(-5, 5);

// B = A * X
$b1 = $a11*$x1 + $a12*$x2 + $a13*$x3;
$b2 = $a21*$x1 + $a22*$x2 + $a23*$x3;
$b3 = $a31*$x1 + $a32*$x2 + $a33*$x3;

