$matA = " `\begin{pmatrix} $a11 & $a12 & $a13 \\ $a21 & $a22 & $a23 \\ $a31 & $a32 & $a33 \end{pmatrix}` ";
$matB = " `\begin{pmatrix} $b1 \\ $b2 \\ $b3 \end{pmatrix}` ";

